// Demo 1-2-1 goalkeeper (slot 1, tactic "GK + 1-2-1"): hold the goal line on
// the ball -> own goal centre axis, sweep free or opponent-carried balls that
// reach the box, and open play with a short pass to the deepest open teammate
// when in possession.
function update(game) {
  const { me, ball, teammates, opponents } = game;
  const home = me.team === 'home';
  const lineX = home ? 6 : 94;
  const goalX = home ? 0 : 100;

  if (me.hasBall) {
    distribute(me, teammates, opponents, home);
    return;
  }

  const ownerTeam = ball.owner === null ? null : ball.owner.split('-')[0];

  // Sweep: a free or opponent-carried ball inside our box, close enough to
  // claim it before the attacker does.
  const inOwnBox = home ? ball.position.x < 20 : ball.position.x > 80;
  if (ownerTeam !== me.team && inOwnBox
      && distance(me.position, ball.position) < 16) {
    chase(me, ball);
    return;
  }

  // Hold the line: stand where the ball owner -> goal centre segment crosses
  // the keeper line; shade to the ball itself when the source is already
  // between the keeper and the goal.
  let source = ball.position;
  if (ball.owner !== null) {
    const [ownerTeam, ownerSlot] = ball.owner.split('-');
    const roster = ownerTeam === me.team ? teammates : opponents;
    const owner = roster.find((player) => player.slot === Number(ownerSlot));
    if (owner) source = owner.position;
  }
  let targetY = 25;
  const deltaX = goalX - source.x;
  const crossing = deltaX === 0 ? -1 : (lineX - source.x) / deltaX;
  if (crossing > 0) {
    targetY = source.y + crossing * (25 - source.y);
  } else {
    targetY = ball.position.y;
  }
  me.moveToward(lineX, clamp(targetY, 15, 35));
}

function distribute(me, teammates, opponents, home) {
  if (nearestOpponentDistance(me.position, opponents) >= 4.5) {
    const target = bestPass(me, teammates, opponents, home ? 1 : -1);
    if (target) {
      me.shoot(
        target.position.x,
        target.position.y,
        passPower(distance(me.position, target.position)),
      );
      return;
    }
  }
  // Pressed with no outlet, or no open teammate: clear toward midfield.
  me.shoot(home ? 58 : 42, clamp(me.position.y >= 25 ? 40 : 10, 6, 44), 0.95);
}

function clamp(value, min, max) {
  return Math.max(min, Math.min(max, value));
}

function distance(a, b) {
  return Math.hypot(b.x - a.x, b.y - a.y);
}

function nearestOpponentDistance(point, opponents) {
  let best = Infinity;
  for (const o of opponents) {
    best = Math.min(best, distance(point, o.position));
  }
  return best;
}

function laneBlocked(from, to, opponents, margin) {
  const dx = to.x - from.x;
  const dy = to.y - from.y;
  const lengthSq = dx * dx + dy * dy;
  for (const o of opponents) {
    let t = lengthSq === 0
      ? 0
      : ((o.position.x - from.x) * dx + (o.position.y - from.y) * dy) / lengthSq;
    t = clamp(t, 0, 1);
    if (distance({ x: from.x + t * dx, y: from.y + t * dy }, o.position) < margin) {
      return true;
    }
  }
  return false;
}

// Most advanced open teammate: clear pass lane, target not crowded, scored
// by forward progress + openness - length.
function bestPass(me, teammates, opponents, dir) {
  let best = null;
  let bestScore = -Infinity;
  for (const mate of teammates) {
    const d = distance(me.position, mate.position);
    if (d < 6 || d > 46) continue;
    const openness = nearestOpponentDistance(mate.position, opponents);
    if (openness < 5) continue;
    if (laneBlocked(me.position, mate.position, opponents, 4)) continue;
    const score = dir * (mate.position.x - me.position.x)
      + 1.5 * Math.min(openness, 12)
      - 0.2 * d;
    if (score > bestScore) {
      bestScore = score;
      best = mate;
    }
  }
  return best;
}

// Friction-aware pass power: with 0.95/tick decay the ball travels about
// 42 units per 1.0 of power, so aim just past the receiver.
function passPower(d) {
  return clamp(d / 42, 0.45, 0.95);
}

// Lead pursuit: aim slightly ahead of a moving ball.
function chase(me, ball) {
  me.moveToward(
    clamp(ball.position.x + ball.velocity.vx * 3, 0, 100),
    clamp(ball.position.y + ball.velocity.vy * 3, 0, 50),
  );
}

// Demo 1-2-1 fixo (slot 2, tactic "GK + 1-2-1"): the deep central defender.
// Builds from the back in possession, offers the outlet behind the play when
// the team attacks, covers the central lane between the ball and the own goal
// when defending, and harasses: steps out to meet the ball as soon as it
// enters his zone instead of waiting in the cover line.
var held = 0;

function update(game) {
  const { me, ball, teammates, opponents } = game;
  const home = me.team === 'home';
  const X = (x) => (home ? x : 100 - x);
  held = me.hasBall ? held + 1 : 0;

  if (me.hasBall) {
    onBall(me, teammates, opponents, X(100), home ? 1 : -1, home, held);
    return;
  }

  const ownerTeam = ball.owner === null ? null : ball.owner.split('-')[0];
  if (ownerTeam === me.team) {
    // Support: step forward behind the play, tracking the ball line.
    me.moveToward(X(30), clamp(25 + (ball.position.y - 25) * 0.25, 14, 36));
    return;
  }
  if (ownerTeam !== null) {
    // Harass: press the carrier as the closest player, and step out to meet
    // the ball as soon as it enters the fixo's zone.
    if (me.isClosestToBall() || distance(me.position, ball.position) < 14) {
      chase(me, ball);
      return;
    }
    // Cover the central lane between the ball and the own goal.
    me.moveToward(X(16), clamp(25 + (ball.position.y - 25) * 0.65, 12, 38));
    return;
  }
  if (me.isClosestToBall()) {
    chase(me, ball);
    return;
  }
  me.moveToward(X(22), clamp(25 + (ball.position.y - 25) * 0.3, 15, 35));
}

function onBall(me, teammates, opponents, attackX, dir, home, held) {
  const distGoal = Math.abs(me.position.x - attackX);
  const keeper = opponents.find((o) => o.slot === 1) ?? null;
  const cornerY = keeper && keeper.position.y >= 25 ? 17 : 33;

  // Tap-in: the keeper cannot cover the far corner from this close; an open
  // shot is also taken whenever the keeper is drawn far enough off it.
  const keeperGap = keeper ? Math.abs(keeper.position.y - cornerY) : Infinity;
  // A keeper holding the carrier's side is committed away from the far
  // corner, so he no longer clogs the shot lane.
  const keeperCommitted = Boolean(
    keeper
    && Math.abs(keeper.position.y - 25) > 1
    && (keeper.position.y - 25) * (me.position.y >= 25 ? 1 : -1) > 0,
  );
  const blockers = keeperCommitted ? opponents.filter((o) => o !== keeper) : opponents;
  const laneClear = !laneBlocked(me.position, { x: attackX, y: cornerY }, blockers, 2.5);
  if (laneClear
      && (distGoal < 12
        || (distGoal < 30 && keeperGap > 0.26 * distGoal + 2.4))) {
    me.shoot(attackX, cornerY, 1);
    return;
  }

  // Pressed: release the ball to the least-marked open teammate, or clear —
  // but only once the reception shield has allowed a first turn (markers
  // converge on the reception point, so an instant outlet restarts the
  // scramble). A defender inside 3 forces the release immediately.
  const nearest = nearestOpponentDistance(me.position, opponents);
  if (nearest < 4.5 && (held >= 2 || nearest < 3)) {
    const outlet = bestPass(me, teammates, opponents, dir, false);
    if (outlet) {
      me.shoot(
        outlet.position.x,
        outlet.position.y,
        passPower(distance(me.position, outlet.position)),
      );
      return;
    }
    me.shoot(home ? 62 : 38, me.position.y >= 25 ? 40 : 10, 0.95);
    return;
  }

  // In space: carry the ball forward; release it only to a teammate who is
  // clearly better placed (well ahead, open, lane clear), after the shield.
  const target = held >= 2 ? bestPass(me, teammates, opponents, dir, true) : null;
  if (target) {
    me.shoot(
      target.position.x,
      target.position.y,
      passPower(distance(me.position, target.position)),
    );
    return;
  }

  dribbleAtGoal(me, opponents, attackX);
}

function dribbleAtGoal(me, opponents, attackX) {
  let nearest = null;
  let nd = Infinity;
  for (const o of opponents) {
    const d = distance(me.position, o.position);
    if (d < nd) {
      nd = d;
      nearest = o;
    }
  }
  const ty = nearest && nd < 8
    ? me.position.y + (me.position.y >= nearest.position.y ? 12 : -12)
    : 25 + (me.position.y - 25) * 0.5;
  me.dribble(attackX, clamp(ty, 4, 46));
}

